import '../entities/benchmark_item.dart';

/// All benchmark persistence goes through this repository — the
/// presentation layer never touches Hive directly (§18.8).
abstract class BenchmarkRepository {
  List<BenchmarkItem> getAll();

  List<BenchmarkItem> getActive();

  /// Creates a new benchmark. `id`/`createdAt`/`updatedAt` are generated by
  /// the implementation. A newly created benchmark starts active — there
  /// is no other way for the user to see its comparison than to create it
  /// with intent to use it right away; they can deactivate it afterward.
  void create({
    required String name,
    required double price,
    required String currencyCode,
  });

  /// §4.2 edit — always bumps `updatedAt` (TC-RPM-002), which is what the
  /// §4.2 "top" ordering rule sorts on.
  void edit({
    required String id,
    required String name,
    required double price,
    required String currencyCode,
  });

  void delete(String id);

  void activate(String id);

  void deactivate(String id);
}
